import sys
import numpy as np

sys.path.insert(0, '/testbed')

from keras.src import backend
from keras.src.optimizers.sgd import SGD
from keras.src.optimizers.adam import Adam
from keras.src.optimizers.loss_scale_optimizer import LossScaleOptimizer


def max_depth_during(fn):
    max_depth = 0

    def profiler(frame, event, arg):
        nonlocal max_depth
        if event in ('call', 'return', 'c_call', 'c_return', 'c_exception', 'exception', 'line'):
            d = 0
            f = frame
            while f is not None:
                d += 1
                f = f.f_back
            if d > max_depth:
                max_depth = d
        return profiler

    old_prof = sys.getprofile()
    old_trace = sys.gettrace()
    sys.setprofile(profiler)
    sys.settrace(profiler)
    try:
        fn()
    finally:
        sys.setprofile(old_prof)
        sys.settrace(old_trace)
    return max_depth


def run_medium():
    optimizer = SGD(
        learning_rate=0.08,
        momentum=0.6,
        nesterov=True,
        clipnorm=0.9,
    )

    variables = [
        backend.Variable(np.array([1.0 + i, -0.5 * i], dtype='float32'), name=f'mvar_{i}')
        for i in range(4)
    ]
    grads = [
        np.array([2.0 + 0.2 * i, -1.5 - 0.1 * i], dtype='float32')
        for i in range(4)
    ]

    optimizer.apply(grads, variables)
    for var in variables:
        assert tuple(var.shape) == (2,)


def run_complex():
    inner_optimizer = Adam(
        learning_rate=0.01,
        beta_1=0.8,
        beta_2=0.95,
